// Generated by Cypress Author on 2026-11-18

describe('Dynamic Page View & Resolution', () => {
  it('visit /about with published page data → renders dynamic title, description, and sanitized story content', () => {
    cy.intercept('GET', '**/api/pages/home:about*', {
      statusCode: 200,
      body: {
        id: 'about-1',
        slug: 'home:about',
        title: 'About Delisha Marie',
        description: 'Culinary journey, handcrafted recipes, and love for home-cooked food.',
        content: `
          <p>Delisha Marie is a passionate cook and creator.</p>
          <p>Visit the kitchen for new recipes: <a href="{{kitchenUrl}}">Visit the Kitchen</a></p>
        `,
        updated_at: new Date().toISOString(),
      },
    }).as('getAboutPage');

    cy.visit('/about');
    cy.wait('@getAboutPage');

    cy.get('dm-dynamic-page').should('be.visible');
    cy.get('dm-dynamic-page').contains('h1', 'About Delisha Marie').should('be.visible');
    cy.get('dm-dynamic-page')
      .contains('p', 'Culinary journey, handcrafted recipes, and love for home-cooked food.')
      .should('be.visible');

    cy.get('.story').should('contain.text', 'Delisha Marie is a passionate cook and creator.');
    cy.get('.story a')
      .contains('Visit the Kitchen')
      .should('have.attr', 'href')
      .and('not.include', '{{kitchenUrl}}');
  });

  it('visit non-existent slug with 404 response → displays Page Not Found fallback state', () => {
    cy.intercept('GET', '**/api/pages/home:missing-page*', {
      statusCode: 404,
      body: { error: 'Not found' },
    }).as('getMissingPage');

    cy.visit('/missing-page');
    cy.wait('@getMissingPage');

    cy.get('dm-dynamic-page').contains('h1', 'Page Not Found').should('be.visible');
    cy.get('dm-dynamic-page')
      .contains('p', 'The page you are looking for does not exist or has not been published yet.')
      .should('be.visible');
  });
});
